pub fn find_matches(&mut self) -> Result<Vec<AstGrepMatch>, MethodFindError> {
        let stdout = run_ast_grep_rule(&self.method, &self.directory)?;

        let trimmed = stdout.trim();
        if trimmed.is_empty() {
            self.matches.clear();
            return Ok(Vec::new());
        }

        // parse JSON array or newline-delimited objects
        let selector_items: Vec<SelectorAstGrepMatch> = if trimmed.starts_with('[') {
            serde_json::from_str(trimmed)?
        } else {
            trimmed
                .lines()
                .map(str::trim)
                .filter(|l| !l.is_empty())
                .map(|line| serde_json::from_str::<SelectorAstGrepMatch>(line))
                .collect::<Result<Vec<_>, _>>()?
        };

        let mut items: Vec<AstGrepMatch> = Vec::with_capacity(selector_items.len());

        for selector in selector_items {
            let file = selector.file.clone();
            let top_text = selector.text.clone();

            // 1) Try byte-offset based extraction (preferred)
            if let Some(((impl_text, impl_range_opt), (method_text, method_range_opt))) =
                extract_texts_by_offset(&selector)
            {
                // ensure non-optional ByteRange fields by falling back to a default ByteRange
                let impl_range = impl_range_opt.unwrap_or_else(empty_byte_range);
                let method_range = method_range_opt.unwrap_or_else(empty_byte_range);

                items.push(AstGrepMatch {
                    file,
                    top_text,
                    impl_text,
                    impl_range,
                    method_text,
                    method_range,
                });
                continue;
            }

            // 2) Fallback to order-based extraction (secondary array order)
            let mut impl_text = "<no impl>".to_string();
            let mut impl_range: ByteRange = empty_byte_range();
            let mut method_text = "<no method>".to_string();
            let mut method_range: ByteRange = empty_byte_range();

            if let Some(sec) = selector
                .meta_variables
                .as_ref()
                .and_then(|m| m.multi.as_ref())
                .and_then(|mm| mm.secondary.as_ref())
            {
                if sec.len() > 0 {
                    if let Some(t) = sec
                        .get(0)
                        .and_then(|e| e.text.as_ref())
                        .map(|s| s.trim().to_string())
                    {
                        impl_text = t;
                    }
                    impl_range = sec
                        .get(0)
                        .and_then(|e| e.range.as_ref())
                        .and_then(|r| r.byte_offset.clone())
                        .unwrap_or_else(empty_byte_range);
                }
                if sec.len() > 1 {
                    if let Some(t) = sec
                        .get(1)
                        .and_then(|e| e.text.as_ref())
                        .map(|s| s.trim().to_string())
                    {
                        method_text = t;
                    }
                    method_range = sec
                        .get(1)
                        .and_then(|e| e.range.as_ref())
                        .and_then(|r| r.byte_offset.clone())
                        .unwrap_or_else(empty_byte_range);
                }
            }

            items.push(AstGrepMatch {
                file,
                top_text,
                impl_text,
                impl_range,
                method_text,
                method_range,
            });
        }

        // deterministic ordering: file -> method_text
        items.sort_by(|a, b| a.file.cmp(&b.file).then(a.method_text.cmp(&b.method_text)));

        // store results in the struct and return them
        self.matches = items.clone();
        Ok(items)
    }

